import 'dart:convert';
import 'dart:io';

import 'package:collection/collection.dart';
import 'package:glob/glob.dart';
import 'package:uploader/src/enum/enums.dart';

/// The platforms uploader builds for, which are the only ones a stub has to
/// be verified on.
const List<String> builtPlatformKeys = ["android", "ios"];

/// The first line of every `pubspec_overrides.yaml` uploader writes. Finding
/// it at startup means an earlier run ended before it could restore the
/// project.
const String pluginStubOverridesMarker =
    "# Generated by uploader for pluginStubs and removed when the run ends.";

/// The result of turning one package into a stub.
class PluginStubPlan {
  final String name;

  /// Null when only the package's assets or fonts are pruned.
  final AppPlatform? strippedPlatform;

  /// The stub's pubspec, as plain maps and lists ready to be encoded.
  final Map<String, dynamic> pubspec;

  /// Federated implementation packages the stub no longer depends on. They
  /// must leave the graph too, otherwise Flutter registers them on their own.
  /// A platform uploader does not build, such as `macos` sharing
  /// `shared_preferences_foundation` with `ios`, does not keep one.
  final List<String> droppedImplementations;

  /// The `default_package` of every stripped platform. One a built platform
  /// still uses stays in the graph and stays registered, unless it is
  /// stubbed itself.
  final List<String> strippedImplementations;

  /// False when the package declared no native side on [strippedPlatform], so
  /// a stub would change nothing.
  final bool removesNativeCode;

  /// Asset files, relative to the package root, the stub no longer declares.
  final List<String> prunedAssets;

  /// What [prunedAssets] and their resolution variants weigh on disk.
  final int prunedAssetBytes;

  /// Font families the stub no longer declares.
  final List<String> prunedFonts;

  /// What the files of [prunedFonts] weigh on disk.
  final int prunedFontBytes;

  const PluginStubPlan({
    required this.name,
    required this.strippedPlatform,
    required this.pubspec,
    required this.droppedImplementations,
    this.strippedImplementations = const [],
    required this.removesNativeCode,
    this.prunedAssets = const [],
    this.prunedAssetBytes = 0,
    this.prunedFonts = const [],
    this.prunedFontBytes = 0,
  });

  bool get changesPackage =>
      removesNativeCode || prunedAssets.isNotEmpty || prunedFonts.isNotEmpty;

  List<String> get strippedPlatformKeys => switch (strippedPlatform) {
    AppPlatform.all => builtPlatformKeys,
    AppPlatform.ios => const ["ios"],
    AppPlatform.android => const ["android"],
    null => const [],
  };

  /// Every package that must no longer be registered on
  /// [strippedPlatformKeys].
  List<String> get excludedPackages =>
      {name, ...droppedImplementations, ...strippedImplementations}.toList();
}

class PluginStubHelper {
  /// Top level folders a stub never needs.
  static const _alwaysSkippedFolders = {
    ".dart_tool",
    ".git",
    ".github",
    "build",
    "example",
    "test",
  };

  static const _nativeFoldersByPlatform = {
    AppPlatform.ios: {"ios"},
    AppPlatform.android: {"android"},
    AppPlatform.all: {"android", "ios", "darwin", "macos", "linux", "windows"},
  };

  Set<String> skippedFolders(AppPlatform? strippedPlatform) => {
    ..._alwaysSkippedFolders,
    ...?_nativeFoldersByPlatform[strippedPlatform],
  };

  /// Builds the pubspec of a stub from the package's own [pubspec].
  ///
  /// The Dart API is untouched; only the plugin declaration for
  /// [strippedPlatform] goes, together with the federated implementations it
  /// pointed to, the asset files matching [assetPatterns] and the font
  /// families in [fontFamilies]. [packageRoot] is where the original package
  /// lives, so its relative `path:` dependencies and its asset folders can
  /// still be found from the copy.
  PluginStubPlan planStub({
    required String name,
    required Map<dynamic, dynamic> pubspec,
    required AppPlatform? strippedPlatform,
    required String packageRoot,
    List<String> assetPatterns = const [],
    List<String> fontFamilies = const [],
  }) {
    final stub = _plainMap(pubspec);
    final flutter = stub["flutter"];
    final plugin = flutter is Map<String, dynamic> ? flutter["plugin"] : null;
    final platforms = plugin is Map<String, dynamic>
        ? plugin["platforms"]
        : null;

    var removesNativeCode = false;
    final droppedImplementations = <String>[];
    final strippedImplementations = <String>[];

    final canStrip =
        strippedPlatform != null &&
        plugin is Map<String, dynamic> &&
        (platforms is Map<String, dynamic> ||
            strippedPlatform == AppPlatform.all);

    if (canStrip) {
      final platformMap = platforms is Map<String, dynamic>
          ? platforms
          : <String, dynamic>{};
      final strippedKeys = strippedPlatform == AppPlatform.all
          ? platformMap.keys.toList()
          : [strippedPlatform.value];

      final strippedDefaults = <String>{};
      for (final key in strippedKeys) {
        final entry = platformMap[key];
        if (entry == null) continue;
        removesNativeCode = true;
        final defaultPackage = entry is Map ? entry["default_package"] : null;
        if (defaultPackage is String) strippedDefaults.add(defaultPackage);
      }

      if (strippedPlatform == AppPlatform.all && platforms == null) {
        removesNativeCode = true;
      }
      strippedKeys.forEach(platformMap.remove);
      strippedImplementations.addAll(strippedDefaults);

      final defaultsStillBuilt = {
        for (final key in builtPlatformKeys)
          if (platformMap[key] case {"default_package": final String package})
            package,
      };
      final dependencies = stub["dependencies"];
      for (final implementation in strippedDefaults) {
        if (defaultsStillBuilt.contains(implementation)) continue;
        if (dependencies is Map && dependencies.containsKey(implementation)) {
          dependencies.remove(implementation);
          droppedImplementations.add(implementation);
          platformMap.removeWhere(
            (_, entry) =>
                entry is Map && entry["default_package"] == implementation,
          );
        }
      }
      if (platformMap.isEmpty) (flutter as Map).remove("plugin");
    }

    final prunedAssets = assetPatterns.isEmpty
        ? const <String>[]
        : _pruneAssets(
            stub["flutter"],
            packageRoot: packageRoot,
            patterns: assetPatterns.map(Glob.new).toList(),
          );
    final prunedFonts = fontFamilies.isEmpty
        ? const <Map<String, dynamic>>[]
        : _pruneFonts(stub["flutter"], families: fontFamilies.toSet());

    _absolutizePathDependencies(stub["dependencies"], packageRoot);
    stub
      ..remove("dev_dependencies")
      ..remove("dependency_overrides")
      ..remove("resolution")
      ..remove("workspace");

    return PluginStubPlan(
      name: name,
      strippedPlatform: strippedPlatform,
      pubspec: stub,
      droppedImplementations: droppedImplementations,
      strippedImplementations: strippedImplementations,
      removesNativeCode: removesNativeCode,
      prunedAssets: prunedAssets,
      prunedAssetBytes: prunedAssets.fold(
        0,
        (total, asset) => total + _assetBytes(packageRoot, asset),
      ),
      prunedFonts: [for (final font in prunedFonts) "${font["family"]}"],
      prunedFontBytes: prunedFonts.fold(
        0,
        (total, font) => total + _fontBytes(packageRoot, font),
      ),
    );
  }

  /// Rewrites the `fonts` list of [flutter] without the [families] and
  /// returns the entries it removed.
  List<Map<String, dynamic>> _pruneFonts(
    dynamic flutter, {
    required Set<String> families,
  }) {
    final fonts = flutter is Map<String, dynamic> ? flutter["fonts"] : null;
    if (fonts is! List) return const [];

    bool isPruned(dynamic entry) =>
        entry is Map<String, dynamic> && families.contains(entry["family"]);

    final pruned = fonts.where(isPruned).cast<Map<String, dynamic>>().toList();
    final kept = fonts.whereNot(isPruned).toList();
    if (kept.isEmpty) {
      (flutter as Map).remove("fonts");
    } else {
      (flutter as Map)["fonts"] = kept;
    }
    return pruned;
  }

  int _fontBytes(String packageRoot, Map<String, dynamic> family) {
    final fonts = family["fonts"];
    if (fonts is! List) return 0;

    return fonts
        .whereType<Map>()
        .map((font) => font["asset"])
        .whereType<String>()
        .map((asset) => File("$packageRoot/$asset"))
        .where((file) => file.existsSync())
        .fold(0, (total, file) => total + file.lengthSync());
  }

  /// Rewrites the `assets` list of [flutter] without the files matching
  /// [patterns] and returns those files.
  ///
  /// A folder entry stands for every file directly inside it, so a folder
  /// with a pruned file is replaced by its remaining files. Their resolution
  /// variants (`2.0x/`, `3.0x/`) are still found from those files, and the
  /// pruned ones lose theirs.
  List<String> _pruneAssets(
    dynamic flutter, {
    required String packageRoot,
    required List<Glob> patterns,
  }) {
    final assets = flutter is Map<String, dynamic> ? flutter["assets"] : null;
    if (assets is! List) return const [];

    bool isPruned(String asset) =>
        patterns.any((pattern) => pattern.matches(asset));

    final pruned = <String>[];
    final kept = <dynamic>[];
    for (final entry in assets) {
      final path = entry is Map ? entry["path"] : entry;
      if (path is! String) {
        kept.add(entry);
      } else if (!path.endsWith("/")) {
        isPruned(path) ? pruned.add(path) : kept.add(entry);
      } else {
        final files = _filesDirectlyIn(packageRoot, path);
        final prunedFiles = files.where(isPruned).toSet();
        if (prunedFiles.isEmpty) {
          kept.add(entry);
          continue;
        }
        pruned.addAll(prunedFiles);
        for (final file in files.where((file) => !prunedFiles.contains(file))) {
          kept.add(entry is Map ? {...entry, "path": file} : file);
        }
      }
    }

    if (kept.isEmpty) {
      (flutter as Map).remove("assets");
    } else {
      (flutter as Map)["assets"] = kept;
    }
    return pruned;
  }

  List<String> _filesDirectlyIn(String packageRoot, String folder) {
    final directory = Directory("$packageRoot/$folder");
    if (!directory.existsSync()) return const [];

    return directory
        .listSync()
        .whereType<File>()
        .map((file) => "$folder${file.uri.pathSegments.last}")
        .toList()
      ..sort();
  }

  int _assetBytes(String packageRoot, String asset) {
    final file = File("$packageRoot/$asset");
    final fileName = file.uri.pathSegments.last;

    final variants = file.parent.existsSync()
        ? file.parent
              .listSync()
              .whereType<Directory>()
              .where((folder) => _resolutionFolder.hasMatch(_nameOf(folder)))
              .map((folder) => File("${folder.path}/$fileName"))
        : const <File>[];

    return [file, ...variants]
        .where((candidate) => candidate.existsSync())
        .fold(0, (total, candidate) => total + candidate.lengthSync());
  }

  String _nameOf(FileSystemEntity entity) =>
      entity.uri.pathSegments.lastWhere((segment) => segment.isNotEmpty);

  static final _resolutionFolder = RegExp(r"^\d+(\.\d+)?x$");

  /// The implementations [plans] take out of the graph: dropped by one stub
  /// and depended on by no other.
  Set<String> leftGraph(List<PluginStubPlan> plans) {
    final stillDepended = {
      for (final plan in plans)
        if (plan.pubspec["dependencies"] case final Map dependencies)
          ...dependencies.keys.map((name) => "$name"),
    };
    return {
      for (final plan in plans) ...plan.droppedImplementations,
    }.difference(stillDepended);
  }

  /// The `dependency_overrides` the run resolves with: the project's own
  /// overrides followed by one path override per stub, so a stub wins over an
  /// override of the same package.
  ///
  /// [baseOverrides] must be the overrides pub would apply without uploader,
  /// because the ones in `pubspec_overrides.yaml` replace those in
  /// `pubspec.yaml` instead of adding to them.
  Map<String, dynamic> mergeOverrides({
    required Map<dynamic, dynamic>? baseOverrides,
    required Map<String, String> stubPaths,
  }) => {
    ...?baseOverrides == null ? null : _plainMap(baseOverrides),
    for (final entry in stubPaths.entries) entry.key: {"path": entry.value},
  };

  /// JSON is valid YAML, so the file needs no YAML writer.
  String encodeOverridesFile(Map<String, dynamic> overrides) =>
      "$pluginStubOverridesMarker\n"
      "${const JsonEncoder.withIndent("  ").convert({"dependency_overrides": overrides})}\n";

  String encodePubspec(Map<String, dynamic> pubspec) =>
      "${const JsonEncoder.withIndent("  ").convert(pubspec)}\n";

  /// The absolute root of [name] according to a decoded
  /// `.dart_tool/package_config.json` found at [packageConfigUri].
  String? packageRoot({
    required Map<dynamic, dynamic> packageConfig,
    required Uri packageConfigUri,
    required String name,
  }) {
    final packages = packageConfig["packages"];
    if (packages is! List) return null;

    for (final package in packages) {
      if (package is Map && package["name"] == name) {
        final rootUri = package["rootUri"];
        if (rootUri is! String) return null;
        return _trimSeparator(
          packageConfigUri.resolve(rootUri).normalizePath().toFilePath(),
        );
      }
    }
    return null;
  }

  /// Every `package (platform)` pair that is still registered natively after
  /// the stubbed graph was resolved, read from a decoded
  /// `.flutter-plugins-dependencies`. Null [pluginsDependencies] means the app
  /// has no plugins left at all.
  List<String> remainingRegistrations({
    required Map<dynamic, dynamic>? pluginsDependencies,
    required List<PluginStubPlan> plans,
  }) {
    final plugins = pluginsDependencies?["plugins"];
    if (plugins is! Map) return const [];

    final remaining = <String>[];
    for (final plan in plans) {
      for (final platformKey in plan.strippedPlatformKeys) {
        final registered = plugins[platformKey];
        if (registered is! List) continue;
        final names = registered
            .whereType<Map>()
            .map((plugin) => plugin["name"])
            .toSet();
        remaining.addAll(
          plan.excludedPackages
              .where(names.contains)
              .map((excluded) => "$excluded ($platformKey)"),
        );
      }
    }
    return remaining;
  }

  void _absolutizePathDependencies(dynamic dependencies, String packageRoot) {
    if (dependencies is! Map) return;

    for (final dependency in dependencies.values) {
      if (dependency is! Map) continue;
      final path = dependency["path"];
      if (path is! String || Uri.file(path).isAbsolute) continue;
      dependency["path"] = _trimSeparator(
        Uri.directory(packageRoot).resolve(path).normalizePath().toFilePath(),
      );
    }
  }

  String _trimSeparator(String path) =>
      path.length > 1 && (path.endsWith("/") || path.endsWith(r"\"))
      ? path.substring(0, path.length - 1)
      : path;

  Map<String, dynamic> _plainMap(Map<dynamic, dynamic> map) => {
    for (final entry in map.entries) "${entry.key}": _plain(entry.value),
  };

  dynamic _plain(dynamic value) => switch (value) {
    Map() => _plainMap(value),
    List() => value.map(_plain).toList(),
    _ => value,
  };
}
